/**
 * The single definition of what an instance exposes. The nginx config, `just urls`, `just open`
 * and the proxy's network aliases are all derived from this list, so a new service is one entry
 * here and nothing else.
 *
 * Two namespaces, deliberately disjoint:
 *   public   `<service>.<instance>.localhost` — owned by the shared proxy, used by the browser
 *            AND by the instance containers (that is what keeps the Keycloak issuer identical).
 *   upstream `<service>.<instance>.internal`     — owned by the containers, used only by proxy_pass.
 *
 * `upstream.kind` has a third value besides `devServer`/`container`: `external`, for a service the
 * shared proxy fronts that is neither a container we run nor a host dev server — today just
 * `tiles`, reverse-proxying `https://tiles.swcode.io` (see EXTERNAL_SERVICES below and, for what
 * that unlocks, `tilesCorsAndRewrite`'s own comment).
 */

// nginx variable names may only contain [A-Za-z0-9_], but an instance identifier can contain
// hyphens (see instance.mjs's normaliseIdentifier) — so every per-instance nginx variable is built
// through this one substitution instead of each map re-deriving its own. This is what keeps two
// instances' maps from colliding once every instance's generated conf is `docker cp`'d into the
// same shared proxy container and included into one nginx http context: an un-scoped variable name
// would let the last-loaded instance's map silently win for every instance's server blocks.
export function instanceScopedNginxVariable(base, instance) {
  return `${base}_${instance.replace(/-/g, '_')}`;
}

const LOCALSTACK_CORS = `
    # LocalStack 4.x doesn't reliably emit ACAO for S3 presigned-URL GETs.
    # Inject CORS at the reverse-proxy layer (dev only).
    if ($request_method = OPTIONS) {
      add_header Access-Control-Allow-Origin  "$http_origin" always;
      add_header Access-Control-Allow-Methods "GET, PUT, POST, DELETE, HEAD, OPTIONS" always;
      add_header Access-Control-Allow-Headers "*" always;
      add_header Access-Control-Max-Age       "86400" always;
      add_header Vary                         "Origin" always;
      return 204;
    }

    proxy_hide_header Access-Control-Allow-Origin;
    proxy_hide_header Access-Control-Allow-Credentials;
    proxy_hide_header Access-Control-Allow-Methods;
    proxy_hide_header Access-Control-Allow-Headers;
    proxy_hide_header Access-Control-Expose-Headers;

    add_header Access-Control-Allow-Origin   "$http_origin" always;
    add_header Access-Control-Allow-Methods  "GET, PUT, POST, DELETE, HEAD, OPTIONS" always;
    add_header Access-Control-Allow-Headers  "*" always;
    add_header Access-Control-Expose-Headers "ETag" always;
    add_header Vary                          "Origin" always;
`;

// Strict CORS, unlike LOCALSTACK_CORS above: it reflects `$http_origin` only for this instance's
// three frontend origins (resolved into the instance-scoped `$limesurvey_allowed_origin_<instance>`
// variable by the map below), and omits the header entirely for anything else. Do not level this
// down to LOCALSTACK_CORS's laxer reflect-anything behaviour — LimeSurvey has no other access
// control in front of it in dev.
function limesurveyCorsLocation(instance) {
  const variable = instanceScopedNginxVariable('limesurvey_allowed_origin', instance);
  return `
    if ($request_method = OPTIONS) {
      add_header Access-Control-Allow-Origin  $${variable} always;
      add_header Access-Control-Allow-Methods "GET, POST, PUT, PATCH, DELETE, OPTIONS" always;
      add_header Access-Control-Allow-Headers "*" always;
      add_header Access-Control-Max-Age       "86400" always;
      add_header Vary                         "Origin" always;
      return 204;
    }

    # Hidden before it is re-added, so an endpoint that sets its own origin header cannot end up
    # sending the two conflicting values browsers reject outright.
    proxy_hide_header Access-Control-Allow-Origin;
    add_header Access-Control-Allow-Origin $${variable} always;
    add_header Vary                        "Origin" always;
`;
}

// An nginx `map` is only legal in http context, and the generated per-instance file is included in
// http context — so this has to be emitted once, above every `server` block, never inside one. The
// variable name is instance-scoped: the shared proxy includes every instance's file into one http
// context, so an un-scoped `$limesurvey_allowed_origin` would let whichever instance's file loads
// last silently win for every instance's server blocks (verified against a real nginx — see
// render.test.mjs). Origins come from the already-built dev-server services (`describeService`'s
// own output) rather than a re-declared copy of the public hostname template, so this map can
// never drift out of step with the hostnames `describeService` actually produces.
function limesurveyCorsMap(devServers, instance) {
  const originLines = devServers.map((service) => `  "${service.url}" $http_origin;`).join('\n');
  const variable = instanceScopedNginxVariable('limesurvey_allowed_origin', instance);
  return `
map $http_origin $${variable} {
  default "";
${originLines}
}
`;
}

export const DEV_SERVERS = Object.freeze([
  Object.freeze({ name: 'app', project: 'app' }),
  Object.freeze({ name: 'cms', project: 'cms' }),
  Object.freeze({ name: 'boards', project: 'urboards' }),
]);

/**
 * `service` is the Compose service name, which becomes the `.internal` alias.
 * `openPath` is appended by `just open` because for these two nobody ever wants the root.
 */
